    if (ccxtGoWholePrintedCallee (goTranspiler, printedValue) !== 'this.RequestId') {
        return undefined;
    }
    let declaration;
    try {
        declaration = goTranspiler.getChecker ().getResolvedSignature (initializer)?.declaration?.resolve ();
    } catch (e) {
        return undefined;
    }
