    if (unique.every ((c) => c.startsWith ('plain') || (c === 'typedmap') || (c === 'typedslice'))) {
        return (kind (unique) === 'slice') ? 'typedslice' : 'typedmap';
    }
    return 'deref:' + kind (unique);
