// the argument texts of a call whose opening parenthesis sits at `open`, or undefined
// when the parentheses do not balance — an unproven call site must never pass the proof
function goBalancedCallArgs (text: string, open: number): string[] | undefined {
    const args: string[] = [];
    let depth = 0;
    let current = '';
    let quote: string | undefined;
    for (let i = open; i < text.length; i++) {
        const ch = text[i];
        if (quote !== undefined) {
            current += ch;
            if (ch === '\\') {
                current += text[i + 1] ?? '';
                i++;
                continue;
            }
            if (ch === quote) {
                quote = undefined;
            }
            continue;
        }
        if ((ch === '"') || (ch === "'") || (ch === '`')) {
            quote = ch;
            current += ch;
            continue;
        }
        if ((ch === '/') && (text[i + 1] === '/')) {
            while ((i < text.length) && (text[i] !== '\n')) { i++; }
            continue;
        }
        if (ch === '(') {
            depth++;
            if (depth > 1) { current += ch; }
            continue;
        }
        if (ch === ')') {
            depth--;
            if (depth === 0) {
                if (current.trim().length > 0) { args.push (current.trim ()); }
                return args;
            }
            current += ch;
            continue;
        }
        if ((ch === ',') && (depth === 1)) {
            args.push (current.trim ());
            current = '';
            continue;
        }
        current += ch;
    }
    return undefined;
}

