        let parent: any = current.parent;
        while ((parent?.kind === SyntaxKind.ParenthesizedExpression) || (parent?.kind === SyntaxKind.AsExpression)
            || (parent?.kind === SyntaxKind.NonNullExpression)) {
            current = parent;
            parent = parent.parent;
        }
